insert into public.breeds (id, name_de, size_class, "group", base_traits, notes) values
  ('labrador-retriever', 'Labrador Retriever', 'large', 'Apportierhunde', '{"energy": 4, "trainability": 5, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 3, "sensitivity": 3, "guarding": 1, "independence": 2}'::jsonb, 'Sehr menschenbezogen und verfressen – Futter ist ein starker Verstärker. Braucht Kopf- und Nasenarbeit, neigt zu Übergewicht.'),
  ('deutscher-schaeferhund', 'Deutscher Schäferhund', 'large', 'Hüte- und Treibhunde', '{"energy": 4, "trainability": 5, "sociability_people": 3, "sociability_dogs": 3, "prey_drive": 3, "sensitivity": 4, "guarding": 4, "independence": 2}'::jsonb, 'Arbeitsfreudig und eng an seine Menschen gebunden. Braucht klare Struktur und Beschäftigung, sonst sucht er sich Aufgaben (Wachen, Kontrollieren).'),
  ('golden-retriever', 'Golden Retriever', 'large', 'Apportierhunde', '{"energy": 4, "trainability": 5, "sociability_people": 5, "sociability_dogs": 5, "prey_drive": 2, "sensitivity": 3, "guarding": 1, "independence": 2}'::jsonb, 'Freundlich und kooperativ. Liebt Apportier- und Suchspiele. Junge Goldies sind oft stürmisch bei Begrüßungen.'),
  ('franzoesische-bulldogge', 'Französische Bulldogge', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 2, "trainability": 3, "sociability_people": 5, "sociability_dogs": 3, "prey_drive": 1, "sensitivity": 3, "guarding": 2, "independence": 3}'::jsonb, 'Anhänglich, oft eigensinnig. Kurzköpfig: Hitze und starke Anstrengung meiden, Atmung beobachten.'),
  ('australian-shepherd', 'Australian Shepherd', 'medium', 'Hüte- und Treibhunde', '{"energy": 5, "trainability": 5, "sociability_people": 3, "sociability_dogs": 3, "prey_drive": 3, "sensitivity": 4, "guarding": 3, "independence": 2}'::jsonb, 'Sehr aktiv und lernfreudig, neigt zu Überdrehtheit. Ruhe-Training ist genauso wichtig wie Auslastung. Hütetrieb kann sich gegen Joggern, Radfahrern oder Kindern zeigen.'),
  ('chihuahua', 'Chihuahua', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 3, "trainability": 3, "sociability_people": 3, "sociability_dogs": 2, "prey_drive": 2, "sensitivity": 4, "guarding": 3, "independence": 3}'::jsonb, 'Klein, aber selbstbewusst. Wird oft getragen statt erzogen – auch er braucht Training und Sozialkontakt. Kälteempfindlich.'),
  ('jack-russell-terrier', 'Jack Russell Terrier', 'small', 'Terrier', '{"energy": 5, "trainability": 3, "sociability_people": 4, "sociability_dogs": 2, "prey_drive": 5, "sensitivity": 3, "guarding": 3, "independence": 4}'::jsonb, 'Viel Energie und ausgeprägter Jagdtrieb. Braucht Beschäftigung für Kopf und Körper und ein sicheres Rückruf-Training.'),
  ('dackel', 'Dackel (Teckel)', 'small', 'Dachshunde', '{"energy": 3, "trainability": 2, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 5, "sensitivity": 3, "guarding": 4, "independence": 5}'::jsonb, 'Selbstständig und jagdlich motiviert, trifft gern eigene Entscheidungen. Geduld und Motivation statt Druck. Rücken schonen (Treppen, Sprünge).'),
  ('border-collie', 'Border Collie', 'medium', 'Hüte- und Treibhunde', '{"energy": 5, "trainability": 5, "sociability_people": 3, "sociability_dogs": 3, "prey_drive": 4, "sensitivity": 5, "guarding": 2, "independence": 1}'::jsonb, 'Extrem lernfähig und reizempfänglich. Ohne Kopfarbeit und Ruhephasen entstehen schnell Zwangs- oder Hüteverhalten (z. B. Autos jagen, Schatten fixieren).'),
  ('yorkshire-terrier', 'Yorkshire Terrier', 'small', 'Terrier', '{"energy": 3, "trainability": 3, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 3, "sensitivity": 3, "guarding": 3, "independence": 3}'::jsonb, 'Lebhaft und mutig, oft wachsam und bellfreudig. Fell braucht regelmäßige Pflege.'),
  ('malteser', 'Malteser', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 2, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 4, "guarding": 2, "independence": 2}'::jsonb, 'Sanft und menschenbezogen. Neigt zu Problemen beim Alleinbleiben, wenn es nicht schrittweise geübt wird.'),
  ('havaneser', 'Havaneser', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 3, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 3, "guarding": 1, "independence": 2}'::jsonb, 'Fröhlich und verspielt, lernt gern Tricks. Sehr auf Menschen bezogen.'),
  ('shih-tzu', 'Shih Tzu', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 2, "trainability": 3, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 3, "guarding": 2, "independence": 3}'::jsonb, 'Ruhig und freundlich, teils eigensinnig. Kurzköpfig: Hitze meiden. Fell- und Augenpflege wichtig.'),
  ('mops', 'Mops', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 2, "trainability": 3, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 3, "guarding": 1, "independence": 3}'::jsonb, 'Gemütlich und anhänglich. Kurzköpfig: Hitze und Überanstrengung meiden, auf Gewicht achten.'),
  ('beagle', 'Beagle', 'medium', 'Laufhunde', '{"energy": 4, "trainability": 2, "sociability_people": 5, "sociability_dogs": 5, "prey_drive": 5, "sensitivity": 3, "guarding": 1, "independence": 4}'::jsonb, 'Nasenhund mit starkem Jagdtrieb und lauter Stimme. Freilauf nur mit sehr sicherem Rückruf. Nasenarbeit ist ideale Auslastung.'),
  ('english-cocker-spaniel', 'Englischer Cocker Spaniel', 'medium', 'Stöberhunde', '{"energy": 4, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 4, "sensitivity": 4, "guarding": 2, "independence": 2}'::jsonb, 'Fröhlich und arbeitswillig, stöbert gern. Kann Ressourcen (Futter, Spielzeug) verteidigen – frühzeitig Tauschspiele üben.'),
  ('berner-sennenhund', 'Berner Sennenhund', 'giant', 'Schweizer Sennenhunde', '{"energy": 2, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 3, "guarding": 3, "independence": 2}'::jsonb, 'Gutmütig und ruhig. Wächst langsam – Gelenke im ersten Lebensjahr schonen. Hitzeempfindlich.'),
  ('boxer', 'Deutscher Boxer', 'large', 'Molosser', '{"energy": 4, "trainability": 3, "sociability_people": 5, "sociability_dogs": 3, "prey_drive": 2, "sensitivity": 3, "guarding": 4, "independence": 2}'::jsonb, 'Verspielt und körperbetont, lange jugendlich. Impulskontrolle und ruhige Begrüßungen gezielt üben.'),
  ('rhodesian-ridgeback', 'Rhodesian Ridgeback', 'large', 'Laufhunde', '{"energy": 3, "trainability": 2, "sociability_people": 3, "sociability_dogs": 3, "prey_drive": 4, "sensitivity": 4, "guarding": 4, "independence": 4}'::jsonb, 'Selbstständig und reserviert gegenüber Fremden. Konsequent, aber fair und ruhig führen; Jagdtrieb beachten.'),
  ('magyar-vizsla', 'Magyar Vizsla', 'large', 'Vorstehhunde', '{"energy": 5, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 4, "sensitivity": 5, "guarding": 1, "independence": 2}'::jsonb, 'Sehr anhänglich und sensibel, braucht viel Bewegung und Nähe. Neigt zu Problemen beim Alleinbleiben.'),
  ('weimaraner', 'Weimaraner', 'large', 'Vorstehhunde', '{"energy": 5, "trainability": 3, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 5, "sensitivity": 4, "guarding": 3, "independence": 3}'::jsonb, 'Jagdlich hoch motiviert und energiegeladen. Braucht Aufgaben wie Dummy- oder Fährtenarbeit.'),
  ('grosspudel', 'Großpudel', 'large', 'Gesellschafts- und Begleithunde', '{"energy": 4, "trainability": 5, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 2, "sensitivity": 4, "guarding": 2, "independence": 2}'::jsonb, 'Sehr intelligent und lernfreudig. Liebt Kopfarbeit und Tricks. Fell regelmäßig scheren.'),
  ('zwergpudel', 'Klein- und Zwergpudel', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 3, "trainability": 5, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 2, "sensitivity": 4, "guarding": 2, "independence": 2}'::jsonb, 'Lernfreudig und aufmerksam. Braucht trotz Größe echte Beschäftigung.'),
  ('cavalier-king-charles-spaniel', 'Cavalier King Charles Spaniel', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 2, "trainability": 4, "sociability_people": 5, "sociability_dogs": 5, "prey_drive": 2, "sensitivity": 4, "guarding": 1, "independence": 1}'::jsonb, 'Sanft, freundlich und anpassungsfähig. Sehr menschenbezogen.'),
  ('zwergspitz', 'Zwergspitz (Pomeranian)', 'small', 'Spitze und Hunde vom Urtyp', '{"energy": 3, "trainability": 3, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 2, "sensitivity": 3, "guarding": 4, "independence": 3}'::jsonb, 'Aufmerksam und bellfreudig. Wachsamkeit früh in ruhige Bahnen lenken.'),
  ('rottweiler', 'Rottweiler', 'large', 'Molosser', '{"energy": 3, "trainability": 4, "sociability_people": 3, "sociability_dogs": 2, "prey_drive": 2, "sensitivity": 3, "guarding": 5, "independence": 3}'::jsonb, 'Ruhig, selbstsicher und schutzbereit. Gute Sozialisierung mit Menschen und Hunden ist besonders wichtig.'),
  ('dobermann', 'Dobermann', 'large', 'Pinscher und Schnauzer', '{"energy": 4, "trainability": 5, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 3, "sensitivity": 4, "guarding": 4, "independence": 2}'::jsonb, 'Wachsam, sensibel und eng an seine Menschen gebunden. Braucht Bewegung und klare, ruhige Führung.'),
  ('berger-blanc-suisse', 'Weißer Schweizer Schäferhund', 'large', 'Hüte- und Treibhunde', '{"energy": 3, "trainability": 4, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 2, "sensitivity": 4, "guarding": 3, "independence": 2}'::jsonb, 'Sanfter als der Deutsche Schäferhund, teils zurückhaltend. Gut sozialisieren, um Unsicherheit vorzubeugen.'),
  ('siberian-husky', 'Siberian Husky', 'large', 'Schlittenhunde', '{"energy": 5, "trainability": 2, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 5, "sensitivity": 2, "guarding": 1, "independence": 5}'::jsonb, 'Lauffreudig, unabhängig und mit starkem Jagdtrieb. Freilauf ist oft schwierig. Zugsport ist ideale Auslastung.'),
  ('deutsch-kurzhaar', 'Deutsch Kurzhaar', 'large', 'Vorstehhunde', '{"energy": 5, "trainability": 4, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 5, "sensitivity": 3, "guarding": 2, "independence": 3}'::jsonb, 'Vielseitiger Jagdhund mit hohem Bewegungsbedarf. Ohne Aufgabe wird der Jagdtrieb schnell zum Problem.'),
  ('leonberger', 'Leonberger', 'giant', 'Molosser', '{"energy": 2, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 3, "guarding": 3, "independence": 2}'::jsonb, 'Gelassen und familienfreundlich. Langsames Wachstum – Gelenke schonen. Leinenführigkeit früh üben, solange er noch klein ist.'),
  ('deutsche-dogge', 'Deutsche Dogge', 'giant', 'Molosser', '{"energy": 2, "trainability": 3, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 2, "sensitivity": 4, "guarding": 3, "independence": 3}'::jsonb, 'Sanfter Riese, oft sensibel. Kurze Lebenserwartung, früh Senior. Gelenke im Wachstum schonen.'),
  ('hovawart', 'Hovawart', 'large', 'Pinscher und Schnauzer', '{"energy": 3, "trainability": 3, "sociability_people": 3, "sociability_dogs": 3, "prey_drive": 3, "sensitivity": 3, "guarding": 5, "independence": 4}'::jsonb, 'Selbstbewusst und wachsam, reift spät. Braucht konsequente, faire Erziehung und klare Regeln beim Thema Bewachen.'),
  ('malinois', 'Belgischer Schäferhund (Malinois)', 'large', 'Hüte- und Treibhunde', '{"energy": 5, "trainability": 5, "sociability_people": 3, "sociability_dogs": 2, "prey_drive": 4, "sensitivity": 5, "guarding": 4, "independence": 1}'::jsonb, 'Hochtriebiger Arbeitshund. Braucht viel Training, Ruhe-Management und erfahrene Menschen. Kein Anfängerhund.'),
  ('west-highland-white-terrier', 'West Highland White Terrier', 'small', 'Terrier', '{"energy": 3, "trainability": 3, "sociability_people": 4, "sociability_dogs": 3, "prey_drive": 4, "sensitivity": 3, "guarding": 3, "independence": 4}'::jsonb, 'Selbstbewusst und fröhlich, typisch Terrier. Buddeln und Jagen sind normales Verhalten – Alternativen anbieten.'),
  ('shetland-sheepdog', 'Shetland Sheepdog (Sheltie)', 'small', 'Hüte- und Treibhunde', '{"energy": 4, "trainability": 5, "sociability_people": 3, "sociability_dogs": 4, "prey_drive": 3, "sensitivity": 5, "guarding": 3, "independence": 1}'::jsonb, 'Lernfreudig und sensibel, oft geräuschempfindlich und bellfreudig. Sanftes Training.'),
  ('collie', 'Collie (Langhaar)', 'large', 'Hüte- und Treibhunde', '{"energy": 3, "trainability": 5, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 2, "sensitivity": 5, "guarding": 2, "independence": 2}'::jsonb, 'Sanft und sensibel, reagiert stark auf Stimmung. Nur weiches, belohnungsbasiertes Training.'),
  ('bichon-frise', 'Bichon Frisé', 'small', 'Gesellschafts- und Begleithunde', '{"energy": 3, "trainability": 4, "sociability_people": 5, "sociability_dogs": 4, "prey_drive": 1, "sensitivity": 3, "guarding": 1, "independence": 2}'::jsonb, 'Fröhlich und verspielt. Alleinbleiben behutsam aufbauen. Fell regelmäßig pflegen.'),
  ('dalmatiner', 'Dalmatiner', 'large', 'Laufhunde', '{"energy": 5, "trainability": 3, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 3, "sensitivity": 4, "guarding": 2, "independence": 3}'::jsonb, 'Ausdauernd und energiegeladen. Braucht viel Bewegung. Gehörlosigkeit kommt rassetypisch vor.'),
  ('whippet', 'Whippet', 'medium', 'Windhunde', '{"energy": 3, "trainability": 3, "sociability_people": 4, "sociability_dogs": 4, "prey_drive": 5, "sensitivity": 4, "guarding": 1, "independence": 3}'::jsonb, 'Drinnen ruhig, draußen ein Sprinter mit Hetztrieb. Sicherer Freilauf braucht Training oder eingezäunte Flächen.'),
  ('englische-bulldogge', 'Englische Bulldogge', 'medium', 'Molosser', '{"energy": 1, "trainability": 2, "sociability_people": 5, "sociability_dogs": 3, "prey_drive": 1, "sensitivity": 3, "guarding": 2, "independence": 4}'::jsonb, 'Gemütlich und freundlich, teils stur. Kurzköpfig: Hitze und Anstrengung meiden.'),
  ('cane-corso', 'Cane Corso Italiano', 'giant', 'Molosser', '{"energy": 3, "trainability": 3, "sociability_people": 3, "sociability_dogs": 2, "prey_drive": 2, "sensitivity": 3, "guarding": 5, "independence": 3}'::jsonb, 'Schutzbereit und kraftvoll. Frühe, gute Sozialisierung und souveräne Führung sind entscheidend.')
