-- 42 häufige Rassen in DACH. ENTWURF (KI-generiert), reviewed_by = null → fachliche Freigabe nötig.
-- base_traits: 1 (gering) bis 5 (stark). Mischling = bis zu 2 Elternrassen in dogs, unbekannt = keine Rasse.
on conflict (id) do update set name_de = excluded.name_de, size_class = excluded.size_class,
  "group" = excluded."group", base_traits = excluded.base_traits, notes = excluded.notes;
